def solve():
    shuffled = input().strip()
    substring = input().strip()

    shuffled_len = len(shuffled)

    # Find valid k
    candidates = []

    for k in range(1, shuffled_len + 1):
        k_str = str(k)
        if k + len(k_str) == shuffled_len:
            # This k is valid
            # Try to construct n with k digits from shuffled, removing digits of k_str
            digits_available = list(shuffled)

            # Remove digits of k_str
            k_str_list = list(k_str)
            valid = True
            for digit in k_str_list:
                if digit in digits_available:
                    digits_available.remove(digit)
                else:
                    valid = False
                    break

            if not valid or len(digits_available) != k:
                continue

            # Now try to form smallest n of length k containing substring
            n = construct_smallest_n(k, digits_available, substring)
            if n is not None:
                candidates.append(n)

    # Return the smallest candidate
    candidates.sort(key=lambda x: (len(str(x)), x))
    print(candidates[0])

def construct_smallest_n(k, digits, substring):
    """Construct smallest k-digit number from digits containing substring"""
    from itertools import permutations

    # Try all positions where substring can be placed
    best = None

    for pos in range(k - len(substring) + 1):
        # Try to place substring at position pos
        result = try_place_substring(k, digits, substring, pos)
        if result is not None:
            if best is None or int(result) < int(best):
                best = result

    return best

def try_place_substring(k, digits, substring, pos):
    """Try to place substring at position pos in the result"""
    from collections import Counter

    # Create result array
    result = [None] * k

    # Place substring
    for i, ch in enumerate(substring):
        result[pos + i] = ch

    # Count remaining digits needed
    digits_copy = list(digits)
    for ch in substring:
        if ch in digits_copy:
            digits_copy.remove(ch)
        else:
            return None  # substring contains digit not available

    digits_copy.sort()

    # Fill remaining positions to make smallest number
    # But first position cannot be 0 (unless k=1 and n=0)
    for i in range(k):
        if result[i] is None:
            if i == 0 and k > 1:
                # First position, must be non-zero
                found = False
                for j, d in enumerate(digits_copy):
                    if d != '0':
                        result[i] = d
                        digits_copy.pop(j)
                        found = True
                        break
                if not found:
                    return None  # Cannot place non-zero at start
            else:
                # Can use any digit
                result[i] = digits_copy.pop(0)

    result_str = ''.join(result)

    # Validate: no leading zero (except single "0")
    if len(result_str) > 1 and result_str[0] == '0':
        return None

    return result_str

