def find_element(n, k):
    # Base case: after 0 steps, sequence is [1]
    if n == 1:
        return 1

    # Length of sequence after step n-1 is 2^n - 1
    # Middle position is 2^(n-1)
    mid = 2 ** (n - 1)

    if k < mid:
        # k is in the left half (which is the sequence from step n-1)
        return find_element(n - 1, k)
    elif k == mid:
        # k is at the middle position
        return n
    else:
        # k is in the right half (which is also the sequence from step n-1)
        # The right half starts at position mid+1, so we adjust k
        return find_element(n - 1, k - mid)

