def smallest_divisor(n):
    """Find the smallest divisor of n greater than 1"""
    if n % 2 == 0:
        return 2
    # Check odd divisors
    i = 3
    while i * i <= n:
        if n % i == 0:
            return i
        i += 2
    return n

def solve(n, k):
    """Add f(n) to n exactly k times"""
    # If n is even, f(n) = 2 always
    if n % 2 == 0:
        return n + 2 * k

    # If n is odd, do one operation to make it even
    f_n = smallest_divisor(n)
    n = n + f_n
    # Now n is even, so f(n) = 2 for all remaining operations
    return n + 2 * (k - 1)

