MAX_VAL = (1 << 32) - 1  # 2^32 - 1

def execute(start, end, multiplier):
    """Execute commands from start to end with given multiplier.
    Returns (total_adds, overflow_occurred)"""
    total = 0
    overflow = False
    i = start

    while i < end:
        cmd = commands[i].split()

        if cmd[0] == "for":
            n = int(cmd[1])
            new_multiplier = multiplier * n

            # Check if this multiplication would overflow our tracking
            if new_multiplier > MAX_VAL:
                new_multiplier = MAX_VAL + 1  # Mark as definitely overflowed

            # Find the matching end
            end_idx = matching[i]

            # Recursively execute the loop body
            loop_total, loop_overflow = execute(i + 1, end_idx, new_multiplier)

            if loop_overflow:
                overflow = True

            total += loop_total
            if total > MAX_VAL:
                overflow = True

            i = end_idx + 1

        elif cmd[0] == "end":
            i += 1

        elif cmd[0] == "add":
            total += multiplier
            if total > MAX_VAL:
                overflow = True
            i += 1

    return total, overflow

