def solve(n, k):
    MOD = 10**9 + 7

    # Precompute factorials and inverse factorials for binomial coefficients
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD

    # Fermat's little theorem for modular inverse
    def modinv(a, m=MOD):
        return pow(a, m - 2, m)

    inv_fact = [1] * (n + 1)
    inv_fact[n] = modinv(fact[n])
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def binom(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    result = 0

    for r in range(n + 1):
        for c in range(n + 1):
            # Number of cells forced to not have 1
            forced_no_one = r * n + c * n - r * c
            # Number of cells that can have anything
            free_cells = (n - r) * (n - c)

            # Calculate contribution
            ways = pow(k - 1, forced_no_one, MOD) * pow(k, free_cells, MOD) % MOD
            ways = ways * binom(n, r) % MOD * binom(n, c) % MOD

            # Apply inclusion-exclusion sign
            if (r + c) % 2 == 0:
                result = (result + ways) % MOD
            else:
                result = (result - ways + MOD) % MOD

    return result

