        out[i][i] = 1
    return out

def matrixMult(pre, post):
    rows = len(pre)
    mid = len(post)
    columns = len(post[0])
    out = [[0]*columns for i in range(rows)]
    for i in range(rows):
        for j in range(columns):
            for k in range(mid):
                out[i][j] += pre[i][k]*post[k][j]
                out[i][j] = out[i][j]%prime
    return out

def matrixExp(base, power):
    if power == 0:
        return unitMatrix(len(base))
    else:
        if power%2 == 0:
            half = matrixExp(base, power//2)  # Use integer division to avoid type issues
            return matrixMult(half, half)
        else:
            half = matrixExp(base, (power-1)//2)  # Use integer division to avoid type issues
            return matrixMult(matrixMult(half, half), base)

